class Solution {
public:
    vector<string> wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> words(wordDict.begin(), wordDict.end());
        unordered_map<int, vector<string>> memo;
        auto dfs = [&](auto self, int idx) -> vector<string> {
            if (idx == (int)s.size()) return {""};
            if (memo.count(idx)) return memo[idx];
            vector<string> res;
            for (int end = idx + 1; end <= (int)s.size(); ++end) {
                string prefix = s.substr(idx, end - idx);
                if (words.count(prefix)) {
                    vector<string> subSentences = self(self, end);
                    for (const string& sub : subSentences) {
                        res.push_back(sub.empty() ? prefix : prefix + " " + sub);
                    }
                }
            }
            return memo[idx] = res;
        };
        return dfs(dfs, 0);
    }
};

class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> words = new HashSet<>(wordDict);
        Map<Integer, List<String>> memo = new HashMap<>();
        return dfs(s, 0, words, memo);
    }
    private List<String> dfs(String s, int idx, Set<String> words, Map<Integer, List<String>> memo) {
        if (idx == s.length()) {
            List<String> base = new ArrayList<>();
            base.add("");
            return base;
        }
        if (memo.containsKey(idx)) return memo.get(idx);
        List<String> res = new ArrayList<>();
        for (int end = idx + 1; end <= s.length(); end++) {
            String prefix = s.substring(idx, end);
            if (words.contains(prefix)) {
                List<String> subSentences = dfs(s, end, words, memo);
                for (String sub : subSentences) {
                    res.add(sub.isEmpty() ? prefix : prefix + " " + sub);
                }
            }
        }
        memo.put(idx, res);
        return res;
    }
}

var wordBreak = function(s, wordDict) {
    const words = new Set(wordDict);
    const memo = new Map();
    const dfs = (idx) => {
        if (idx === s.length) return [""];
        if (memo.has(idx)) return memo.get(idx);
        const res = [];
        for (let end = idx + 1; end <= s.length; end++) {
            const prefix = s.slice(idx, end);
            if (words.has(prefix)) {
                const subSentences = dfs(end);
                for (const sub of subSentences) {
                    res.push(sub === "" ? prefix : prefix + " " + sub);
                }
            }
        }
        memo.set(idx, res);
        return res;
    };
    return dfs(0);
};
